-- Original HSK 1 picture-recognition items with embedded, simple vector illustrations.
-- SVG is rendered as an image (not inserted into the page DOM) by the student diagnostic.
begin;
on conflict (question_id) do update set
 prompt=excluded.prompt,stimulus=excluded.stimulus,options=excluded.options,
 answer_key=excluded.answer_key,explanation=excluded.explanation,metadata=excluded.metadata,
 source_reference=excluded.source_reference,is_published=true,updated_at=now();
commit;
